"""Data catalog for the warehouse: what each table and view is, where it comes from, how often it updates and what
one row is. build.py writes these into the BigQuery descriptions and DATA_DICTIONARY.md.
Keys are "<dataset>.<name>"; a key ending in * covers every name with that prefix (e.g. "markets.crypto_*")."""

FEEDS = "rrp-sec Cloud Run job (cloud/feeds code, SEC sources), hourly at :05"
MARKET = "rrp-markets Cloud Run job (cloud/market code), every 30 min"
NEWEST = "newest write per key wins; a row with deleted = TRUE withdraws the entry"
NOW = "computed when read"
DAILY = "daily"
EQ = "rrp-markets-equities Cloud Run job (cloud/market code), weekdays 22:20 UTC"
FUNDS = FEEDS + " (sec_funds.py, once a day in the 7 AM ET run)"
EXTRACT = FEEDS + " (once a day at 08:05 UTC, last 14 days of filing text)"

DATASETS = {
    "rrp": "Start here: the reading layer, every view named by subject (sec_, insider_, crypto_, stablecoins_, equity_, macro_, yields_, gov_, momentum_, health_).",
    "sec": "SEC data loaded by the rrp-sec job: full-text search hits, filing text, every Form 4 open-market line, company facts (XBRL), the CIK/ticker list and delisting filings.",
    "gov": "CFTC Commitments of Traders, USAspending Defense awards, war.gov contract days, Treasury cash, EIA and degree days (rrp-gov job).",
    "markets": "Crypto, stablecoin, equity and macro data loaded by the rrp-markets jobs (Treasury yields by rrp-gov), plus the pre-warehouse yield and stablecoin history.",
    "ops": "Run logs of the ingest jobs (one row per source per run): feeds_runs for the cloud/feeds code (rrp-sec, rrp-gov), market_runs for the cloud/market code (rrp-markets*, rrp-gov).",
    "staging": "Scratch tables the cloud jobs load before each MERGE. Tables expire after one day.",
}

